head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > removeInstanceNode]<br/>Instance 내부에서 XPath 에 해당하는 노드를 제거합니다. 동일한 XPath 에 여러 노드가 있으면 첫 번째 노드만 제거합니다.",
    "validation" : [
        "xpath(필수) 파라미터로 제거할 노드의 XPath 를 설정할 수 있어야 합니다.",
        "XPath 에 해당하는 노드를 제거해야 합니다.",
        "동일한 XPath 에 여러 노드가 있으면 첫 번째 노드만 제거해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 시나리오 실행 전 instance 원본 보존용 스냅샷
    scwin._origBookstore = WebSquare.xml.serialize(WebSquare.ModelUtil.findInstanceNode("bookstore"));
};



// 특정 instance 노드를 원본 직렬화 문자열로 복원 (자식만 교체하여 wrap 중첩 방지)
scwin._resetNodeFromOrigin = function (xpath, origSerialized) {
    var instNode = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!instNode) return;
    while (instNode.firstChild) instNode.removeChild(instNode.firstChild);
    var origNode = WebSquare.xml.parse(origSerialized).documentElement;
    for (var i = 0; i < origNode.childNodes.length; i++) {
        if (origNode.childNodes[i].nodeType === 1) {
            instNode.appendChild(origNode.childNodes[i].cloneNode(true));
        }
    }
};

// 매 시나리오 실행 전 instance 데이터 원본으로 복구
scwin.resetInstance = function () {
    scwin._resetNodeFromOrigin("bookstore", scwin._origBookstore);
};



// 특정 xpath 노드를 serialize 하여 한 줄 문자열로 반환 (출력용)
scwin.dumpXPath = function (xpath) {
    var node = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!node) return "(node not found)";
    var s = WebSquare.xml.serialize(node);
    return s.replace(/\s+/g, " ").replace(/>\s+</g, "><");
};

// 노드의 element 자식 개수 (text 노드/공백 제외)
scwin.countElementChildren = function (node) {
    if (!node) return 0;
    var cnt = 0;
    for (var i = 0; i < node.childNodes.length; i++) {
        if (node.childNodes[i].nodeType === 1) cnt++;
    }
    return cnt;
};



scwin.btn_removeInstanceNode_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.resetInstance();

    if (scenario === "1") {
        // 시나리오 1 : 동일 xpath 여러 노드 - 첫번째만 제거
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : bookstore/book 제거 (여러 노드 중 첫번째만) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("제거 전 : " + scwin.dumpXPath("bookstore"));

        WebSquare.ModelUtil.removeInstanceNode("bookstore/book");

        wf_body_bottom.getObj("scwin").setReturnValue("제거 후 : " + scwin.dumpXPath("bookstore"));
    } else if (scenario === "2") {
        // 시나리오 2 : 단일 노드 xpath 정상 제거
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 단일 노드 xpath 제거 (bookstore/book[1]/title) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("제거 전 : " + scwin.dumpXPath("bookstore/book[1]"));

        WebSquare.ModelUtil.removeInstanceNode("bookstore/book[1]/title");

        wf_body_bottom.getObj("scwin").setReturnValue("제거 후 : " + scwin.dumpXPath("bookstore/book[1]"));
    }
};
